  get canRedo(): boolean {
    return this.#redoStack.length > 0;
  }

  get undoCount(): number {
    return this.#undoStack.length;
  }

  get redoCount(): number {
    return this.#redoStack.length;
  }

  get nextUndoLabel(): string | undefined {
    return this.#undoStack.at(-1)?.label;
