        const claimsNative =
          file.type === NATIVE_DOCUMENT_MIME_TYPE ||
          file.name.toLowerCase().endsWith(NATIVE_DOCUMENT_EXTENSION);
        if (claimsPsd && !isPsd) {
          throw new TypeError('The selected file does not have a PSD signature.');
