    setCropRectangle(null);
    setTool('move');
    setTransformGestureStatus('Crop cancelled.');
  }, []);

  const applyCrop = useCallback(() => {
    if (!document || !cropRectangle) return;
    try {
      const command = cropDocument(cropRectangle);
