import type { CSSProperties, ReactNode } from 'react';
export function EditorShell({
  children,
  rightDockWidth,
}: {
  readonly children: ReactNode;
  readonly rightDockWidth: number;
}) {
  return (
    <div
      className="app-shell"
      style={{ '--right-dock-width': `${String(rightDockWidth)}px` } as CSSProperties}
    >
      {children}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { COMMAND_SUBMENU_DEFINITIONS, MENU_DEFINITIONS } from '../commands/menuDefinitions.js';
import { buildCommandMenuTree } from '../commands/commandMenuTree.js';
import type { CommandMenu, CommandRegistry } from '../commands/commandTypes.js';
import { CommandMenuSurface } from '../commands/CommandMenuSurface.js';
import { Icon, type IconName } from '../ui/Icon.js';
import { PROFESSIONAL_EDITING_PROFILE } from '../workspace/workspaceProfiles.js';

const quickCommands: ReadonlyArray<{ readonly id: string; readonly icon: IconName }> = [
  { id: 'file.new', icon: 'new' },
  { id: 'file.save', icon: 'save' },
  { id: 'file.export-png', icon: 'export' },
  { id: 'edit.undo', icon: 'undo' },
  { id: 'edit.redo', icon: 'redo' },
];

export function ApplicationMenuBar({ registry }: { readonly registry: CommandRegistry }) {
  const [openMenu, setOpenMenu] = useState<CommandMenu | null>(null);
  const menuBarRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!openMenu) return;
    const close = (event: PointerEvent) => {
      if (!menuBarRef.current?.contains(event.target as Node)) setOpenMenu(null);
    };
    window.addEventListener('pointerdown', close);
    return () => window.removeEventListener('pointerdown', close);
  }, [openMenu]);

  const focusMenu = (menu: CommandMenu, direction: 1 | -1 = 1) => {
    const menus = MENU_DEFINITIONS.filter((item) =>
      PROFESSIONAL_EDITING_PROFILE.menus.includes(item.id),
    );
    const index = menus.findIndex((item) => item.id === menu);
    const next = menus[(index + direction + menus.length) % menus.length];
    if (!next) return;
    setOpenMenu(next.id);
    requestAnimationFrame(() => document.getElementById(`menu-${next.id}`)?.focus());
  };

  return (
    <header className="application-menubar" ref={menuBarRef}>
      <div className="brand" aria-label="FreetoShop Studio">
        <span className="brand-mark">
          <Icon name="brand" />
        </span>
        <span className="brand-name">FreetoShop</span>
      </div>
      <nav className="menu-strip" aria-label="Application menus" role="menubar">
        {MENU_DEFINITIONS.filter((menu) =>
          PROFESSIONAL_EDITING_PROFILE.menus.includes(menu.id),
        ).map((menu) => {
          const nodes = buildCommandMenuTree(
            menu.id,
            [...registry.values()].filter((command) => command.menu === menu.id),
            COMMAND_SUBMENU_DEFINITIONS,
          );
          return (
            <div className="menu-root" key={menu.id}>
              <button
                id={`menu-${menu.id}`}
                className="menu-trigger"
                type="button"
                role="menuitem"
                aria-haspopup="menu"
                aria-expanded={openMenu === menu.id}
                onClick={() => setOpenMenu((current) => (current === menu.id ? null : menu.id))}
                onKeyDown={(event) => {
                  if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    setOpenMenu(menu.id);
                    requestAnimationFrame(() =>
                      document
                        .querySelector<HTMLElement>(`#menu-popup-${menu.id} [role^='menuitem']`)
                        ?.focus(),
                    );
                  } else if (event.key === 'ArrowRight') {
                    event.preventDefault();
                    focusMenu(menu.id, 1);
                  } else if (event.key === 'ArrowLeft') {
                    event.preventDefault();
                    focusMenu(menu.id, -1);
                  }
                }}
              >
                {menu.label}
              </button>
              {openMenu === menu.id && (
                <CommandMenuSurface
                  nodes={nodes}
                  registry={registry}
                  ariaLabel={`${menu.label} commands`}
                  id={`menu-popup-${menu.id}`}
                  onCloseAll={() => {
                    setOpenMenu(null);
                    document.getElementById(`menu-${menu.id}`)?.focus();
                  }}
                  onMoveRootMenu={(direction) => focusMenu(menu.id, direction)}
                />
              )}
            </div>
          );
        })}
      </nav>
      <div className="menubar-spacer" />
      <div className="command-quick-access" aria-label="Quick access commands">
        {quickCommands.map(({ id, icon }) => {
          const command = registry.get(id);
          if (!command) return null;
          return (
            <button
              className="icon-button"
              aria-label={command.label}
              data-command={
                id === 'image.size'
                  ? 'image-size'
                  : id === 'image.canvas-size'
                    ? 'canvas-size'
                    : id === 'filter.last'
                      ? 'filters'
                      : undefined
              }
              title={command.shortcut ? `${command.label} (${command.shortcut})` : command.label}
              disabled={!command.enabled}
              onClick={command.execute}
              key={id}
            >
              <Icon name={icon} />
            </button>
          );
        })}
      </div>
    </header>
  );
}

  const applyImageSize = useCallback(async () => {
    if (!document || parsedImageSize.error || operationAbortRef.current) return;
    if (
      parsedImageSize.width === document.canvas.width &&
      parsedImageSize.height === document.canvas.height
    ) {
      closeSizeDialog();
      notify('Image size is unchanged.');
      return;
    }
    const controller = new AbortController();
    operationAbortRef.current = controller;
    setBusy(true);
    setOperationProgress(0);
    try {
      const result = await getDocumentWorkerClient().run(
        {
          kind: 'resize',
          document,
          width: parsedImageSize.width,
          height: parsedImageSize.height,
          method: imageSizeDraft.method,
        },
        { signal: controller.signal, onProgress: setOperationProgress },
      );
      if (result.kind !== 'resize')
        throw new Error('The resize worker returned an invalid result.');
      const next = runCommand({
        label: 'Resize image',
        execute(current) {
          if (current !== document) {
            throw new Error('The document changed while the image was resizing. Please try again.');
          }
          return result.document;
        },
      });
      if (!next) return;
      closeSizeDialog();
      window.requestAnimationFrame(() => fitTarget(next));
      notify(
        `Image resized to ${String(parsedImageSize.width)} × ${String(parsedImageSize.height)} pixels.`,
      );
    } catch (error) {
      if (isAbortError(error)) notify('Image resize cancelled.');
      else notify(error instanceof Error ? error.message : 'Image resize failed.', 'error');
    } finally {
      if (operationAbortRef.current === controller) operationAbortRef.current = null;
      setOperationProgress(null);
      setBusy(false);
    }
  }, [
    closeSizeDialog,
    document,
    fitTarget,
    getDocumentWorkerClient,
    imageSizeDraft.method,
    notify,
    parsedImageSize,
    runCommand,
  ]);

  const applyFilter = useCallback(
    async (requestedDraft: FilterDraft = filterDraft) => {
      if (!document || !selectedLayer || filterError || operationAbortRef.current) return;
      if (selectedLayer.kind === 'smart-object' && requestedDraft.kind === 'gaussian-blur') {
        const smartFilter = createSmartFilterFromDraft(
          'gaussian-blur',
          requestedDraft,
          makeId('smart-filter'),
        );
        runCommand(
          setSmartObjectFilters(selectedLayer.id, [...selectedLayer.smartFilters, smartFilter]),
        );
        setLastFilter({ kind: 'gaussian-blur', draft: requestedDraft });
        closeSizeDialog();
        notify('Gaussian Blur added as a smart filter.');
        return;
      }
      if (selectedLayer.kind !== 'pixel') return;
      const controller = new AbortController();
      operationAbortRef.current = controller;
      setBusy(true);
      setOperationProgress(0);
      try {
        const worldTransform =
          findLayerWorldTransform(document, selectedLayer.id) ?? selectedLayer.transform;
        const result = await getDocumentWorkerClient().run(
          {
            kind: 'filter',
            layer: selectedLayer,
            selection: document.selection,
            worldTransform,
            draft: requestedDraft,
          },
          { signal: controller.signal, onProgress: setOperationProgress },
        );
        if (result.kind !== 'filter')
          throw new Error('The filter worker returned an invalid result.');
        if (result.patches.length === 0) {
          closeSizeDialog();
          notify(`${FILTER_LABELS[requestedDraft.kind]} made no pixel changes.`);
          return;
        }
        let pixelStore = selectedLayer.pixelStore;
        for (const patch of result.patches) {
          pixelStore = pixelStore.write({
            ...patch,
            pixels: new Uint8ClampedArray(patch.pixels),
          }).store;
        }
        const command = replacePixelStore(
          selectedLayer.id,
          pixelStore,
          `Apply ${FILTER_LABELS[requestedDraft.kind]}`,
        );
        const next = runCommand({
          label: command.label,
          execute(current) {
            if (current !== document) {
              throw new Error(
                'The document changed while the filter was running. Please try again.',
              );
            }
            return command.execute(current);
          },
        });
        if (!next) return;
        closeSizeDialog();
        if (requestedDraft.kind === 'gaussian-blur')
          setLastFilter({ kind: 'gaussian-blur', draft: requestedDraft });
        notify(`${FILTER_LABELS[requestedDraft.kind]} applied destructively.`);
      } catch (error) {
        if (isAbortError(error)) notify('Filter cancelled.');
        else notify(error instanceof Error ? error.message : 'Filter failed.', 'error');
      } finally {
        if (operationAbortRef.current === controller) operationAbortRef.current = null;
        setOperationProgress(null);
        setBusy(false);
      }
    },
